function catalogFields(item={},editing=false){return input('name','物资名称',item.name||'',{full:true})+input('spec','规格',item.spec||'')+input('unit','基本单位',item.unit||'',{max:30,readOnly:editing&&item.referenced,note:editing&&item.referenced?'已有业务引用，基本单位保持不变。':''})+select('categoryId','物资分类',dictionaryOptions(state.categories),item.categoryId||'')+select('trackingMode','库存管理方式',[['unit','逐件管理（一瓶／一件一码）'],['quantity','按数量管理（可小数）']],item.trackingMode||'unit',{readOnly:editing&&item.referenced})+input('code','系统物资编码',item.code||'',{max:64,required:false,readOnly:true,note:editing?'永久识别码，编辑资料不改变已有二维码。':'由系统自动分配，用于识别物资，无需填写。'})+input('remark','物资档案备注（选填）',item.remark||'',{type:'textarea',required:false,full:true,max:2000})+laboratoryFields(item);}
