function receiptCatalogSelection(){const section=el('mw-receipt-catalog');if(!section)return;const selected=el('mw-form').elements.catalogId.value,create=selected==='new',row=state.catalog.find(row=>String(row.id)===selected);el('mw-receipt-match').textContent=create?'填写并确认新物资信息；与本次验收一并保存。':row?'已选择：'+row.name+' · '+row.spec+' · '+row.unit:'请选择已有物资，或新建物资信息。';section.hidden=!create;section.querySelectorAll('input,select,textarea').forEach(field=>{field.disabled=!create;});}
