  if(context.mode==='request-delete'||context.mode==='request-cancel'){body={requestVersion:request.version,reason:required(form,'reason',context.mode==='request-delete'?'删除原因':'作废原因',1000)};path='/requests/'+id(request.id)+(context.mode==='request-cancel'?'/cancel':'');method=context.mode==='request-delete'?'DELETE':'POST';}
